import numpy as np
from scipy.optimize import minimize

def objective(vars):
    x, y, z = vars
    if x <= 0 or y <= 0 or z <= 0:
        return 1e9
    return (2*x**2 + 1) * (2*y**2 + 1) * (2*z**2 + 1) / (x*y + y*z + z*x)

min_val = float('inf')
# Use a grid of starting points
for x0 in np.linspace(0.1, 2.0, 5):
    for y0 in np.linspace(0.1, 2.0, 5):
        for z0 in np.linspace(0.1, 2.0, 5):
            res = minimize(objective, [x0, y0, z0], bounds=((1e-6, None), (1e-6, None), (1e-6, None)))
            if res.success:
                min_val = min(min_val, res.fun)

print(f"Min value: {min_val}")
